<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>WastedToken Mint — Collectible Challenge Coins</title>
<style>
  :root{
    --bg:#0b0d12;
    --bg2:#11141c;
    --panel:#151925;
    --line:#262c3d;
    --gold:#d9ab3c;
    --gold-hi:#ffe08a;
    --ink:#e8e6df;
    --muted:#9aa1b2;
    --serif:Georgia,'Times New Roman',serif;
    --sans:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    background:
      radial-gradient(1200px 700px at 75% -10%, #1a1f2e 0%, transparent 60%),
      radial-gradient(900px 600px at -10% 40%, #141a29 0%, transparent 55%),
      var(--bg);
    color:var(--ink);
    font-family:var(--sans);
    line-height:1.6;
    overflow-x:hidden;
  }
  ::selection{background:var(--gold);color:#10131a}

  /* ---------- header ---------- */
  header{
    position:sticky;top:0;z-index:50;
    display:flex;align-items:center;justify-content:space-between;
    padding:16px 5vw;
    background:rgba(11,13,18,.82);
    backdrop-filter:blur(10px);
    border-bottom:1px solid var(--line);
  }
  .logo{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--ink)}
  .logo-coin{
    width:34px;height:34px;border-radius:50%;
    background:radial-gradient(circle at 32% 30%, var(--gold-hi), var(--gold) 45%, #7a5510 100%);
    box-shadow:0 0 0 2px #3a2f12, 0 2px 10px rgba(217,171,60,.35);
    display:grid;place-items:center;
    font-family:var(--serif);font-weight:900;color:#3d2b06;font-size:18px;
  }
  .logo b{font-family:var(--serif);font-size:1.05rem;letter-spacing:.14em}
  .logo b span{color:var(--gold)}
  nav{display:flex;align-items:center;gap:28px}
  nav a{color:var(--muted);text-decoration:none;font-size:.82rem;letter-spacing:.18em;text-transform:uppercase;transition:color .2s}
  nav a:hover{color:var(--gold-hi)}
  .cart-pill{
    border:1px solid var(--line);border-radius:999px;padding:6px 16px;
    color:var(--ink);font-size:.8rem;letter-spacing:.08em;background:var(--panel);
  }
  .cart-pill b{color:var(--gold)}

  /* ---------- hero ---------- */
  .hero{
    display:grid;grid-template-columns:minmax(320px,1fr) minmax(340px,600px);
    gap:4vw;align-items:center;
    padding:8vh 5vw 10vh;min-height:88vh;max-width:1440px;margin:0 auto;
  }
  .eyebrow{
    color:var(--gold);font-size:.75rem;letter-spacing:.34em;text-transform:uppercase;
    margin-bottom:20px;display:flex;align-items:center;gap:14px;
