<script>
(function(){
"use strict";

/* ================================================================
   Shared 2D helpers (used by hero face textures + edition tiles)
   ================================================================ */

// Draw text along an arc. Assumes ctx already translated to circle center,
// textAlign=center, textBaseline=middle, font/fillStyle set by caller.
// flip=false: top legend (glyph tops point outward). flip=true: bottom legend.
function arcText(g, str, r, center, flip){
  var w = [], total = 0, i;
  for(i=0;i<str.length;i++){ w[i] = g.measureText(str[i]).width; total += w[i]; }
  var a = center + (flip ? 1 : -1) * (total / (2*r));
  for(i=0;i<str.length;i++){
    var half = w[i] / (2*r);
    a += flip ? -half : half;
    g.save();
    g.translate(r*Math.cos(a), r*Math.sin(a));
    g.rotate(a + (flip ? -Math.PI/2 : Math.PI/2));
    g.fillText(str[i], 0, 0);
    g.restore();
    a += flip ? -half : half;
  }
}

/* ================================================================
   HERO COIN — raw WebGL, no libraries
   ================================================================ */

var heroCanvas = document.getElementById('coin-hero');
var gl = heroCanvas.getContext('webgl', {
  antialias:true, preserveDrawingBuffer:true, alpha:false
});

// ---- procedural height-map textures for the two faces ----
// White = raised relief, black = field. Soft gradients are needed for
// normal-map derivation, so we blend a downsampled (blurred) copy with
// the crisp original.
function makeHeightCanvas(draw){
  var c = document.createElement('canvas'); c.width = c.height = 512;
  var x = c.getContext('2d');
  x.fillStyle = '#000'; x.fillRect(0,0,512,512);
  x.fillStyle = '#fff'; x.strokeStyle = '#fff';
  x.textAlign = 'center'; x.textBaseline = 'middle';
  draw(x);
  var s = document.createElement('canvas'); s.width = s.height = 128;
  s.getContext('2d').drawImage(c, 0, 0, 128, 128);
  var o = document.createElement('canvas'); o.width = o.height = 512;
  var ox = o.getContext('2d');
  ox.imageSmoothingEnabled = true;
  ox.drawImage(s, 0, 0, 512, 512);       // soft base
  ox.globalAlpha = 0.55;
  ox.drawImage(c, 0, 0);                 // crisp detail on top
  return o;
}

var frontFace = makeHeightCanvas(function(f){
  // rim
  f.lineWidth = 18; f.beginPath(); f.arc(256,256,232,0,6.2832); f.stroke();
  // inner ring
  f.lineWidth = 4; f.beginPath(); f.arc(256,256,190,0,6.2832); f.stroke();
  // legends
  f.font = '700 36px Georgia, serif';
  f.save(); f.translate(256,256);
  arcText(f,'WASTEDTOKEN MINT',209,-Math.PI/2,false);
  arcText(f,'★ EST. MMXXI ★',209, Math.PI/2,true);
  f.restore();
  // monogram
  f.font = '900 230px Georgia, serif';
  f.fillText('W',256,262);
  // flanking stars
  f.font = '700 42px Georgia, serif';
  f.fillText('★',110,256); f.fillText('★',402,256);
});

var backFace = makeHeightCanvas(function(b){
  b.lineWidth = 18; b.beginPath(); b.arc(256,256,232,0,6.2832); b.stroke();
  b.lineWidth = 4; b.beginPath(); b.arc(256,256,190,0,6.2832); b.stroke();
  b.font = '700 34px Georgia, serif';
  b.save(); b.translate(256,256);
  arcText(b,'CHALLENGE COIN',209,-Math.PI/2,false);
  arcText(b,'★ SERIES 001 ★',209, Math.PI/2,true);
  b.restore();
  b.font = '900 108px Georgia, serif';
  b.fillText('10,000',256,222);
  b.font = '700 54px Georgia, serif';
  b.fillText('TOKENS',256,312);
  // divider bar
  b.fillRect(176,264,160,5);
});

// ---- geometry: coin = front disc + back disc + reeded edge cylinder ----
var SEG = 180, R = 1.0, T = 0.18;
var pos=[], nrm=[], tan=[], uv=[], fac=[], idx=[];

function vert(p,n,t,u,f){
  pos.push(p[0],p[1],p[2]); nrm.push(n[0],n[1],n[2]);
  tan.push(t[0],t[1],t[2]); uv.push(u[0],u[1]); fac.push(f);
}
// front disc (face id 0)
(function(){
  var base = pos.length/3;
  vert([0,0,T/2],[0,0,1],[1,0,0],[0.5,0.5],0);
  for(var i=0;i<=SEG;i++){
    var a=i/SEG*Math.PI*2, x=Math.cos(a)*R, y=Math.sin(a)*R;
    vert([x,y,T/2],[0,0,1],[1,0,0],[0.5+x/(2*R),0.5-y/(2*R)],0);
  }
  for(i=0;i<SEG;i++) idx.push(base, base+1+i, base+2+i);
})();
// back disc (face id 1) — uv mirrored so text reads correctly from behind
(function(){
  var base = pos.length/3;
  vert([0,0,-T/2],[0,0,-1],[-1,0,0],[0.5,0.5],1);
  for(var i=0;i<=SEG;i++){
    var a=i/SEG*Math.PI*2, x=Math.cos(a)*R, y=Math.sin(a)*R;
    vert([x,y,-T/2],[0,0,-1],[-1,0,0],[0.5-x/(2*R),0.5-y/(2*R)],1);
  }
  for(i=0;i<SEG;i++) idx.push(base, base+1+i, base+2+i);
})();
// reeded edge (face id 2) — uv.x carries the raw angle for ridge generation
(function(){
  var base = pos.length/3;
  for(var i=0;i<=SEG;i++){
    var a=i/SEG*Math.PI*2, c=Math.cos(a), s=Math.sin(a);
    vert([c*R,s*R, T/2],[c,s,0],[-s,c,0],[a,0],2);
    vert([c*R,s*R,-T/2],[c,s,0],[-s,c,0],[a,1],2);
  }
  for(i=0;i<SEG;i++){
    var p=base+i*2;
    idx.push(p,p+1,p+2,  p+1,p+3,p+2);
  }
})();

// ---- shaders ----
var VS =
'attribute vec3 aP; attribute vec3 aN; attribute vec3 aT;'+
'attribute vec2 aUV; attribute float aF;'+
'uniform mat4 uMVP;'+
'varying vec3 vN; varying vec3 vT; varying vec2 vUV; varying float vF;'+
'void main(){ vN=aN; vT=aT; vUV=aUV; vF=aF;'+
'  gl_Position = uMVP * vec4(aP,1.0); }';

var FS =
'precision highp float;'+
'varying vec3 vN; varying vec3 vT; varying vec2 vUV; varying float vF;'+
'uniform mat3 uNM;'+
'uniform sampler2D uTexF; uniform sampler2D uTexB;'+
'void main(){'+
'  vec3 n = normalize(vN); vec3 t = normalize(vT); vec3 b = cross(n,t);'+
'  float h = 0.0;'+
'  if(vF < 1.5){'+                                  // front or back face
'    float e = 1.5/512.0; float K = 2.4;'+
'    float hx, hy;'+
'    if(vF < 0.5){'+
'      h  = texture2D(uTexF, vUV).r;'+
'      hx = texture2D(uTexF, vUV+vec2(e,0.)).r - texture2D(uTexF, vUV-vec2(e,0.)).r;'+
'      hy = texture2D(uTexF, vUV+vec2(0.,e)).r - texture2D(uTexF, vUV-vec2(0.,e)).r;'+
'    } else {'+
'      h  = texture2D(uTexB, vUV).r;'+
'      hx = texture2D(uTexB, vUV+vec2(e,0.)).r - texture2D(uTexB, vUV-vec2(e,0.)).r;'+
'      hy = texture2D(uTexB, vUV+vec2(0.,e)).r - texture2D(uTexB, vUV-vec2(0.,e)).r;'+
'    }'+
'    n = normalize(n - K*(hx*t - hy*b));'+          // emboss relief
'    vec2 p = vUV - 0.5;'+                          // gentle convex doming so the
'    n = normalize(n + 0.55*(p.x*t - p.y*b));'+     // specular spot rakes across
'  } else {'+                                       // reeded edge
'    float ridge = sin(vUV.x * 96.0);'+
'    n = normalize(n + t * ridge * 0.8);'+
'    h = 0.35 + 0.2*ridge;'+
'  }'+
'  vec3 N = normalize(uNM * n);'+
'  vec3 V = vec3(0.0, 0.0, 1.0);'+
'  vec3 L  = normalize(vec3( 0.55, 0.65, 0.52));'+
'  vec3 L2 = normalize(vec3(-0.62,-0.34, 0.42));'+
'  float dif  = max(dot(N,L ),0.0);'+
'  float dif2 = max(dot(N,L2),0.0);'+
'  vec3 H1 = normalize(L +V); float sp1 = pow(max(dot(N,H1),0.0), 90.0);'+
'  vec3 H2 = normalize(L2+V); float sp2 = pow(max(dot(N,H2),0.0), 36.0);'+
'  vec3 base = vec3(0.98,0.76,0.34) * (0.58 + 0.55*h);'+
'  vec3 specC = vec3(1.0,0.94,0.78);'+
'  vec3 refl = reflect(-V, N);'+                    // fake vertical env gradient
'  float env = smoothstep(-0.6, 0.9, refl.y) * 0.22;'+
'  float fres = pow(1.0 - max(dot(N,V),0.0), 3.0);'+
'  vec3 col = base * (0.28 + 0.9*dif + 0.28*dif2 + env)'+
'           + specC * (sp1*1.7 + sp2*0.45)'+
'           + base * fres * 0.35;'+
'  col = pow(col, vec3(1.0/1.5));'+
'  gl_FragColor = vec4(col, 1.0);'+
'}';

function makeShader(type, src){
  var s = gl.createShader(type);
  gl.shaderSource(s, src); gl.compileShader(s);
  return s;
}
var prog = gl.createProgram();
gl.attachShader(prog, makeShader(gl.VERTEX_SHADER, VS));
gl.attachShader(prog, makeShader(gl.FRAGMENT_SHADER, FS));
gl.linkProgram(prog);
gl.useProgram(prog);

function attrib(name, data, size){
  var buf = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(data), gl.STATIC_DRAW);
  var loc = gl.getAttribLocation(prog, name);
  gl.enableVertexAttribArray(loc);
  gl.vertexAttribPointer(loc, size, gl.FLOAT, false, 0, 0);
}
attrib('aP', pos, 3); attrib('aN', nrm, 3); attrib('aT', tan, 3);
attrib('aUV', uv, 2); attrib('aF', fac, 1);

var ibuf = gl.createBuffer();
gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, ibuf);
