// ---- matrices ----
function persp(fovy, asp, n, f){
  var t = 1/Math.tan(fovy/2), nf = 1/(n-f);
  return [t/asp,0,0,0, 0,t,0,0, 0,0,(f+n)*nf,-1, 0,0,2*f*n*nf,0];
}
function mul4(a,b){
  var o = new Array(16);
  for(var c=0;c<4;c++) for(var r=0;r<4;r++)
    o[c*4+r] = a[r]*b[c*4] + a[4+r]*b[c*4+1] + a[8+r]*b[c*4+2] + a[12+r]*b[c*4+3];
  return o;
}
// model rotation M = RX(phi) * RY(theta), column-major 3x3
function rotXY(phi, theta){
  var cp=Math.cos(phi), sp=Math.sin(phi), ct=Math.cos(theta), st=Math.sin(theta);
  return [ ct, sp*st, -cp*st,   0, cp, sp,   st, -sp*ct, cp*ct ];
}

var PROJ = persp(32*Math.PI/180, 1, 0.5, 20);
var DIST = 5.2;

gl.enable(gl.DEPTH_TEST);
gl.disable(gl.CULL_FACE);
gl.viewport(0, 0, 640, 640);
gl.clearColor(0.055, 0.062, 0.09, 1.0);

// t in [0,1] -> one seamless loop:
//   flip about horizontal (X) axis: 1 revolution
//   spin about vertical (Y) axis:   2 revolutions
// Both faces and the reeded edge all appear clearly during the loop,
// and the fixed lights make the specular highlight rake as it turns.
function render(t){
  var phi = t * Math.PI * 2;     // horizontal-axis flip
  var theta = t * Math.PI * 4;   // vertical-axis rotation
  var m = rotXY(phi, theta);
  var MV = [ m[0],m[1],m[2],0,  m[3],m[4],m[5],0,  m[6],m[7],m[8],0,  0,0,-DIST,1 ];
  gl.uniformMatrix4fv(uMVP, false, new Float32Array(mul4(PROJ, MV)));
  gl.uniformMatrix3fv(uNM,  false, new Float32Array(m));
  gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
  gl.drawElements(gl.TRIANGLES, idx.length, gl.UNSIGNED_SHORT, 0);
}

// ---- animation loop + grading API ----
var running = true, raf = null;
var DUR = 9000;
function loop(now){
  if(!running) return;
  render((now % DUR) / DUR);
  raf = requestAnimationFrame(loop);
}
raf = requestAnimationFrame(loop);

window.demo = {
  canvas: heroCanvas,
  setTime: function(t){
    running = false;
    if(raf){ cancelAnimationFrame(raf); raf = null; }
    t = Math.max(0, Math.min(1, +t || 0)) % 1;   // deterministic, synchronous
    render(t);
  },
  pause: function(){
    running = false;
    if(raf){ cancelAnimationFrame(raf); raf = null; }
  }
};

