  black: { hi:'#79819a', mid:'#2b2f3a', lo:'#14161d', deep:'#040509', ink:'#b8bfd2', lite:'#8f97ad', denom:'100,000', name:'OBSIDIAN' }
};

function drawEditionCoin(cv, p){
  var S = 420;
  cv.width = S; cv.height = S;
  var g = cv.getContext('2d');
  var cx = S/2, cy = S/2, R = S*0.42;
  g.textAlign = 'center'; g.textBaseline = 'middle';

  // soft ground shadow
  var sh = g.createRadialGradient(cx, cy+16, R*0.55, cx, cy+16, R*1.12);
  sh.addColorStop(0,'rgba(0,0,0,0.5)'); sh.addColorStop(1,'rgba(0,0,0,0)');
  g.fillStyle = sh; g.fillRect(0,0,S,S);

  // edge base metal
  g.beginPath(); g.arc(cx,cy,R,0,6.2832);
  var eg = g.createLinearGradient(cx-R,cy-R,cx+R,cy+R);
  eg.addColorStop(0,p.hi); eg.addColorStop(0.5,p.lo); eg.addColorStop(1,p.deep);
  g.fillStyle = eg; g.fill();

  // reeding ticks around the rim
  for(var i=0;i<110;i++){
    g.save(); g.translate(cx,cy); g.rotate(i/110*Math.PI*2);
    g.fillStyle = (i%2) ? p.hi : p.deep;
    g.globalAlpha = 0.9;
    g.fillRect(R-15, -2.2, 15, 4.4);
    g.restore();
  }

  // face
  g.beginPath(); g.arc(cx,cy,R-15,0,6.2832);
  var fg = g.createRadialGradient(cx-R*0.45, cy-R*0.5, R*0.1, cx, cy, R*1.15);
  fg.addColorStop(0,p.hi); fg.addColorStop(0.45,p.mid); fg.addColorStop(1,p.lo);
  g.fillStyle = fg; g.fill();

  // diagonal sheen band
  g.save();
  g.beginPath(); g.arc(cx,cy,R-15,0,6.2832); g.clip();
  var sg = g.createLinearGradient(cx-R,cy-R,cx+R,cy+R);
  sg.addColorStop(0.30,'rgba(255,255,255,0)');
  sg.addColorStop(0.45,'rgba(255,255,255,0.28)');
  sg.addColorStop(0.56,'rgba(255,255,255,0)');
  g.fillStyle = sg; g.fillRect(0,0,S,S);
  g.restore();

  g.save();
  g.translate(cx,cy);

  // embossed draw: dark shadow lower-right, light catch upper-left, ink on top
  function emboss(fn, d){
    g.save(); g.translate( d, d); g.fillStyle=p.deep; g.strokeStyle=p.deep; g.globalAlpha=0.85; fn(); g.restore();
    g.save(); g.translate(-d,-d); g.fillStyle=p.lite; g.strokeStyle=p.lite; g.globalAlpha=0.85; fn(); g.restore();
    g.fillStyle=p.ink; g.strokeStyle=p.ink; fn();
  }

  // inner ring
  emboss(function(){
    g.lineWidth = 3;
    g.beginPath(); g.arc(0,0,104,0,6.2832); g.stroke();
  }, 1.5);

  // legends
  g.font = '700 25px Georgia, serif';
  emboss(function(){ arcText(g,'WASTEDTOKEN MINT',132,-Math.PI/2,false); }, 1.2);
  emboss(function(){ arcText(g,'★ '+p.denom+' TOKENS ★',132, Math.PI/2,true); }, 1.2);

  // monogram + edition name
  g.font = '900 104px Georgia, serif';
  emboss(function(){ g.fillText('W',0,-14); }, 2);
  g.font = '700 25px Georgia, serif';
  emboss(function(){ g.fillText(p.name,0,62); }, 1.2);

  g.restore();
}

